#[cfg(test)]
mod tests {
    use super::COMMAND_MANIFEST;

    /// The command names registered in `lib.rs`'s `generate_handler![]` block,
    /// parsed from the real macro invocation -- never from a hand-kept copy.
    fn registered_commands() -> Vec<String> {
        const OPEN: &str = "generate_handler![";
        let lib = include_str!("../lib.rs");
        let start = lib
            .find(OPEN)
            .expect("lib.rs must contain a generate_handler! block");

        // Balance `[` / `]` from the macro's opening bracket, so the block end
        // is the real closing bracket rather than the first `]` in a nested
        // path. The block contains no string literals, so this is exact.
        let mut depth: usize = 0;
        let mut end: Option<usize> = None;
        for (idx, byte) in lib.as_bytes().iter().enumerate().skip(start + OPEN.len() - 1) {
            match byte {
                b'[' => depth += 1,
                b']' => {
                    depth -= 1;
                    if depth == 0 {
                        end = Some(idx);
                        break;
                    }
                }
                _ => {}
            }
        }
        let end = end.expect("the generate_handler![ list must be closed");

        let block = &lib[start + OPEN.len()..end];
        let mut names = Vec::new();
        for line in block.lines() {
            // The block is a list of paths with `//` line comments and no
            // string literals, so a raw `//` split is exact here.
            let code = line.split("//").next().unwrap_or_default();
            for entry in code.split(',') {
                let entry = entry.trim();
                if entry.is_empty() {
                    continue;
                }
                let name = entry.rsplit("::").next().unwrap_or(entry).trim();
                names.push(name.to_string());
            }
        }
        names
    }

    /// R-2.3 drift guard (T-2.7): every REGISTERED command must be listed in
    /// [`COMMAND_MANIFEST`]. One-directional by design -- see the module docs.
    ///
    /// Without this guard a command registered in `lib.rs` but missing here
    /// gets no autogenerated permission, so no capability can grant it and it
    /// is denied (and, under `removeUnusedCommands`, dropped) in every
    /// built-in window. This assertion names the exact command that is missing.
    #[test]
    fn every_registered_command_is_in_the_manifest() {
        let registered = registered_commands();

        // Non-vacuity: the parser must really see the macro block's contents,
        // otherwise "every registered command is listed" is trivially true.
        assert!(
            !registered.is_empty(),
            "parsed zero commands out of generate_handler!; the parser is vacuous"
        );
        for name in &registered {
            assert!(
                !name.is_empty()
                    && name
                        .chars()
                        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_'),
                "parsed a non-command token {name} out of generate_handler!"
            );
        }

        let mut missing: Vec<&str> = registered
            .iter()
            .map(String::as_str)
            .filter(|name| !COMMAND_MANIFEST.contains(name))
            .collect();
        missing.sort_unstable();
        missing.dedup();

        assert!(
            missing.is_empty(),
            "command(s) registered in lib.rs but missing from COMMAND_MANIFEST: {missing:?} -- \
             append them here, otherwise they are denied and dropped from every window"
        );
    }

    /// Every REGISTERED command must also have an `allow-<command>` grant in the
    /// hand-authored app permission set, and a capability must reference that set
    /// for the built-in window class -- otherwise the built-in windows lose the
    /// command at runtime even though it is registered.
    ///
    /// Deliberately keyed on the real registrations, not on `COMMAND_MANIFEST`:
    /// a manifest entry that lands ahead of its registration (the pattern later
    /// #3147 sub-tasks use) is exempt until it is actually registered, so this
    /// guard cannot fail mid-chain. Once a command IS registered it must be
    /// granted, or app-manifest resolution denies it to every built-in window.
    #[test]
    fn every_registered_command_is_granted_to_the_built_in_windows() {
        let permission_set = include_str!("../../permissions/app/default.toml");
        let grant_capability = include_str!("../../capabilities/app-commands.json");

        // `AppManifest::commands(...)` autogenerates `allow-<command>` with
        // underscores slugified to dashes.
        let registered = registered_commands();
        let mut ungranted: Vec<&str> = registered
            .iter()
            .map(String::as_str)
            .filter(|command| {
                let identifier = format!("\"allow-{}\"", command.replace('_', "-"));
                !permission_set.contains(&identifier)
            })
            .collect();
        ungranted.sort_unstable();
        ungranted.dedup();

        assert!(
            ungranted.is_empty(),
            "manifest command(s) with no allow-<command> grant in \
             permissions/app/default.toml: {ungranted:?}"
        );

        // The app-manifest default permission set is the only thing that grants
        // these commands; it reaches a window only through a capability that
        // references it by its unprefixed `default` identifier.
        assert!(
            permission_set.contains("[default]"),
            "permissions/app/default.toml must declare a [default] permission set"
        );
        assert!(
            grant_capability.contains("\"default\""),
            "capabilities/app-commands.json must reference the app-manifest default \
             permission set"
        );
        // And it must keep reaching the built-in window class. Losing any label
        // here denies the whole app command surface to that window.
        for label in ["\"main\"", "\"terminal\"", "\"doom\"", "\"app-*\""] {
            assert!(
                grant_capability.contains(label),
                "capabilities/app-commands.json must target the built-in window label {label}"
            );
        }
    }
}
